        id: "dmi-interface-displays",
        title: "۳. واسط ماشین-راهبر (DMI: Driver Machine Interface) و نمایشگرهای کابین",
        content: `واسط ماشین-راهبر (<WikiWord term="DMI" definition="نمایشگر صنعتی داخل کابین راننده جهت نمایش بلادرنگ سرعت، هدف، مدها و آلارم‌ها" />) پنل گرافیکی صنعتی لمسی مستقر در مقابل لکوموتیوران است که بازخورد بصری و صوتی لحظه‌ای از وضعیت سیر ناوگان ارائه می‌دهد:

**اجزا و شاخص‌های نمایشگر DMI:**
۱. **سرعت لحظه‌ای قطار (Current Speed):** نمایش آنالوگ با عقربه روان به همراه عدد دیجیتالی سرعت بر حسب کیلومتر بر ساعت (km/h).
۲. **<WikiWord term="سقف سرعت" definition="حداکثر سرعت مجاز تعیین‌شده در تراک جاری با پله‌های ۵ تایی بین ۰ تا ۷۰ km/h" /> (Ceiling Speed):** نشانگر مجاز روی صفحه که با خط یا رنگ شاخص حداکثر سرعت قانونی تراک فعلی را تعیین می‌کند.
۳. **<WikiWord term="سرعت هدف" definition="سرعت مجازی که قطار در انتهای مسافت هدف به دلیل پیچ، شیب یا اشغالی باید به آن تقلیل یابد" /> (Target Speed):** مقداری که قطار باید در نقطه هدف پیش رو به آن سرعت برسد.
۴. **<WikiWord term="مسافت هدف" definition="فاصله فیزیکی باقیمانده تا نقطه تغییر سقف سرعت یا توقف کامل" /> (Distance to Go):** نوار پیشرفت یا عدد مسافت باقیمانده تا نقطه آغاز شیب ترمز.
۵. **حالت کاری سامانه (Operating Mode Indicator):** نمایش آیکون‌های فعال برای مدهای ATO، ATP، Yard، Restricted Manual و Isolation.
۶. **وضعیت درب‌های مسافری (Door Status):** نمایشگر وضعیت باز بودن، بسته بودن، قفل بودن و نشانگر مجوز باز شدن درب‌های سمت سکو (Door Enable Left / Right).
۷. **شناسه قطار و مقصد:** نمایش کد اختصاص‌یافته به قطار توسط سرویس <WikiWord term="توصیفگر قطار" definition="سرویس مرکزی ردیابی و تعیین شماره یکتای قطارها در CTC" />.

**هشدارهای دیداری و شنیداری (Audible & Visual Alarms):**
- **چراغ هشدار چشمک‌زن:** هنگام نزدیک شدن سرعت لحظه‌ای به مرز سقف مجاز.
- **بازر صوتی ممتد (Buzzer):** در زمان تخطی از سرعت مجاز و هم‌زمان با قطع اتوماتیک نیروی کشش پیشرانه.
- **آلارم صوتی با ریتم ویژه:** هنگام تغییر حالت سیستم از یک مد کاری به مد دیگر (مانند خروج خودکار از مد یارد به ATP).`
