        content: `در محوطه <WikiWord term="دپوی کاوه" definition="مرکز دپو و توقفگاه با ریل‌های اتصال‌زمین در کیلومتر ۷ خط ۱" /> و خطوط پارکینگ توقفگاه قدس، ریل‌ها به شبکه ارت متصل بوده و امکان ارسال کدهای پیوسته تراک وجود ندارد. در این نواحی، سیستم <WikiWord term="ATSD" definition="توقف خودکار قطار در خطر با ترانسپوندرهای ۷ متری پای چراغ سیگنال" /> مسئولیت حفاظت از ناوگان را بر عهده دارد:

**مشخصات ترانسپوندرهای ATSD:**
- **موقعیت نصب:** ترانسپوندرهای فعال در فاصله **۷ متری** قبل از هر <WikiWord term="چراغ سیگنال" definition="چراغ‌های دیداری سیگنالینگ با نماهای سبز، زرد، زرد چشمک‌زن و قرمز" /> نصب می‌شوند.
- **ارتباط با اینترلاکینگ:** سیستم اینترلاکینگ (EIL) وضعیت چراغ را از طریق سه سیگنال منطقی به ترانسپوندر گزارش می‌دهد:
  ۱. **وضعیت Clear:** چراغ دارای نمای سبز یا زرد است؛ قطار بدون مداخله عبور می‌کند.
  ۲. **وضعیت Danger / Red:** چراغ قرمز است؛ ترانسپوندر پیام خطر را به آنتن زیر قطار القا کرده و **ترمز اضطراری فوری** پیش از ورود قطار به محدوده تلاقی یا سوزن فعال می‌گردد.
  ۳. **وضعیت Not Valid:** در صورت قطع کابل یا عدم قطعیت داده، طبق اصل Fail-Safe ترانسپوندر وضعیت را قرمز تلقی کرده و ترمز قطار را فعال می‌کند.`
