      {
        id: "ctc-apps-diag-playback-scheduler",
        title: "۶. ابزارهای تشخیص، بازبینی و برنامه‌ریزی حرکت قطار (Train Scheduler)",
        content: `**۱-۸-۳. تشخیص (Diagnosis):**
نرم‌افزار <WikiWord term="تشخیص" definition="ابزار تحلیلی رویدادها و عیب‌یابی در دو حالت آنلاین و آفلاین" /> ابزاری است که با استفاده از اطلاعات پیام‌های مبادله‌شده، امکان بررسی رویدادها و عوامل بروز مشکلات را با قابلیت جستجو و فیلتر کردن فراهم می‌آورد:
- **حالت‌های کاری:** در دو حالت **برخط (Online)** و **آفلاین (Offline)** کار می‌کند.
- **فیلترسازی:** کاربر می‌تواند پیام‌ها را بر اساس **اولویت** و **شدت (Severity)** فیلتر و اولویت‌بندی کند.

**۱-۸-۴. بازبینی (Playback):**
نرم‌افزار <WikiWord term="بازبینی" definition="ابزار شبیه‌سازی و بازخوانی رویدادها از دیتابیس برای تحلیل و آموزش" /> جهت بررسی مجدد اتفاقات سیستم در محیط گرافیکی و همچنین **آموزش کاربران جدید** به کار می‌رود:
- این نرم‌افزار پیام‌های مبادله شده در یک بازه زمانی انتخابی را با سرعت دلخواه نمایش می‌دهد و وقایع را مجدداً شبیه‌سازی می‌نماید.

**۱-۸-۵. برنامه‌ریزی حرکت قطارها (Train Scheduler):**
نرم‌افزار <WikiWord term="برنامه‌ریزی حرکت قطارها" definition="تدوین زمان‌بندی سیر بر پایه مفاهیم Sequence، Headway و Headway Plan" /> یکی از ارکان مهم سیستم مرکز کنترل است.

**مفاهیم کلیدی برنامه‌ریز حرکت:**
- **مفهوم توالی (Sequence):** نشان‌دهنده همسایگی ایستگاه‌ها، زمان توقف در سکو (Dwell Time) و فاصله زمانی تا سکوی بعدی است. توالی‌ها برای حالت‌های مختلف بهره‌برداری (مثلاً هنگام اجرای عملیات عمرانی در خط) کاملاً قابل تغییر و بازپیکربندی هستند.
- **مفهوم سرفاصله زمانی (Headway):** مشخص‌کننده فاصله زمانی حضور دو قطار متوالی در یک نقطه معین در حالت پایدار (**Steady State**) سیستم می‌باشد.
- **برنامه سرفاصله زمانی (Headway Plan):** از آنجا که حجم و تقاضای تردد مسافر در طول ساعات مختلف شبانه‌روز متغیر است، مفهوم Headway Plan برای تعریف و اعمال سرفاصله‌های متفاوت در بازه‌های مختلف زمانی استفاده می‌شود.`
      }
